import React from "react";
import ReactDOM from "react-dom/client";
import { BrowserRouter, HashRouter } from "react-router-dom";
import App from "./App";
import "./index.css";

ReactDOM.createRoot(document.getElementById("app") as HTMLElement).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React from "react";
import Home from "./pages/Home";
import TheWorkout from "./pages/TheWorkout";
import Instructors from "./pages/Instructors";
import RideFaq from "./pages/RideFaq";
import DigitalPlatform from "./pages/DigitalPlatform";

export default function App() {
  const path = window.location.pathname;

  if (path.endsWith("the-workout.html")) {
    return <TheWorkout />;
  }
  if (path.endsWith("instructors.html")) {
    return <Instructors />;
  }
  if (path.endsWith("ride-faq.html")) {
    return <RideFaq />;
  }
  if (path.endsWith("digital-platform.html")) {
    return <DigitalPlatform />;
  }

  // Default to home
  return <Home />;
}

import React, { useState } from "react";
import { Button } from "./ui/button";

export function Newsletter() {
  const [email, setEmail] = useState("");
  const [status, setStatus] = useState<"idle" | "success" | "error">("idle");

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (email && email.includes("@")) {
      setStatus("success");
    } else {
      setStatus("error");
    }
  };

  return (
    <section className="bg-primary text-white py-24">
      <div className="container mx-auto px-4 max-w-2xl text-center">
        <h2 className="font-display text-4xl md:text-5xl uppercase tracking-widest mb-6">Stay in the Know</h2>
        <p className="text-lg md:text-xl mb-10 text-white/90">
          Get workout tips, class updates, and exclusive offers delivered to your inbox.
        </p>

        {status === "success" ? (
          <div className="bg-white/10 p-6 border border-white/20">
            <h3 className="font-display text-2xl uppercase tracking-widest mb-2">You're In</h3>
            <p>Thanks for subscribing. Welcome to the movement.</p>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="flex flex-col sm:flex-row gap-4">
            <input
              type="email"
              placeholder="Email address"
              value={email}
              onChange={(e) => { setEmail(e.target.value); setStatus("idle"); }}
              className="flex-1 bg-black/20 border border-white/30 text-white placeholder:text-white/60 px-6 py-4 focus:outline-none focus:border-white rounded-none"
              required
            />
            <Button type="submit" className="bg-black hover:bg-black/80 text-white font-display tracking-widest text-xl px-12 py-4 h-auto rounded-none border border-black hover:border-white/50">
              SUBSCRIBE
            </Button>
          </form>
        )}
        {status === "error" && (
          <p className="text-black bg-white inline-block px-4 py-1 mt-4 text-sm font-bold">Please enter a valid email address.</p>
        )}
      </div>
    </section>
  );
}

import React, { useState } from "react";
import Layout from "../components/Layout";
import { Newsletter } from "../components/Newsletter";
import { Button } from "../components/ui/button";

export default function Instructors() {
  const [filter, setFilter] = useState("All Locations");

  const locations = ["All Locations", "New York", "Los Angeles", "London", "Miami", "San Francisco"];
  const instructors = [
    { name: "Dani Reyes", location: "New York", image: "https://images.unsplash.com/photo-1548690312-e3b507d8c110?q=80&w=1470&auto=format&fit=crop" },
    { name: "Marcus Cole", location: "Los Angeles", image: "https://images.unsplash.com/photo-1534438327276-14e5300c3a48?q=80&w=1470&auto=format&fit=crop" },
    { name: "Priya Nair", location: "London", image: "https://images.unsplash.com/photo-1581009146145-b5ef050c2e1e?q=80&w=1470&auto=format&fit=crop" },
    { name: "Jordan Voss", location: "Miami", image: "https://images.unsplash.com/photo-1517836357463-d25dfeac3438?q=80&w=1470&auto=format&fit=crop" },
    { name: "Tessa Kim", location: "San Francisco", image: "https://images.unsplash.com/photo-1518611012118-696072aa579a?q=80&w=1470&auto=format&fit=crop" },
    { name: "Andre Williams", location: "New York", image: "https://images.unsplash.com/photo-1571019614242-c5c5dee9f50b?q=80&w=1470&auto=format&fit=crop" },
    { name: "Sofia Marquez", location: "Los Angeles", image: "https://images.unsplash.com/photo-1599058945522-28d584b6f4ff?q=80&w=1469&auto=format&fit=crop" },
    { name: "Liam Chen", location: "London", image: "https://images.unsplash.com/photo-1541534741688-6078c6bfb5c5?q=80&w=1469&auto=format&fit=crop" }
  ];

  const filteredInstructors = filter === "All Locations" ? instructors : instructors.filter(i => i.location === filter);

  return (
    <Layout>
      <section className="py-24 border-b border-white/10 text-center">
        <div className="container mx-auto px-4">
          <h1 className="font-display text-6xl md:text-8xl tracking-widest uppercase mb-8 text-primary drop-shadow-lg">The Elite</h1>
          <p className="text-xl md:text-2xl max-w-2xl mx-auto text-gray-300 leading-relaxed">
            Meet the instructors pushing you to your absolute limits. 
          </p>
        </div>
      </section>

      <section className="py-20 min-h-[60vh] bg-[#141414]">
        <div className="container mx-auto px-4">

          <div className="mb-16 flex flex-wrap justify-center gap-4">
            {locations.map(loc => (
              <button 
                key={loc}
                onClick={() => setFilter(loc)}
                className={`font-display text-lg tracking-widest uppercase px-6 py-2 transition-colors border ${filter === loc ? "border-primary bg-primary text-white" : "border-white/20 text-gray-400 hover:border-white/60 hover:text-white"}`}
              >
                {loc}
              </button>
            ))}
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
            {filteredInstructors.map((inst, idx) => (
              <div key={idx} className="group relative overflow-hidden aspect-[3/4] bg-secondary border border-white/10 hover:border-primary/50 transition-all duration-300">
                <img src={inst.image} alt={inst.name} className="absolute inset-0 w-full h-full object-cover opacity-60 group-hover:opacity-40 group-hover:scale-105 transition-all duration-500 grayscale" />
                <div className="absolute inset-0 bg-gradient-to-t from-black via-black/40 to-transparent"></div>
                <div className="absolute inset-x-0 bottom-0 p-6 translate-y-4 group-hover:translate-y-0 transition-transform duration-300 flex flex-col justify-end">
                  <span className="text-primary font-display tracking-widest uppercase text-sm mb-1">{inst.location}</span>
                  <h3 className="font-display text-3xl uppercase tracking-widest text-white mb-4">{inst.name}</h3>
                  <Button className="w-full bg-white hover:bg-gray-200 text-black font-display tracking-widest uppercase rounded-none opacity-0 group-hover:opacity-100 transition-opacity duration-300 delay-100">
                    Book a Class
                  </Button>
                </div>
              </div>
            ))}
          </div>

          {filteredInstructors.length === 0 && (
            <div className="text-center py-20 text-gray-500 font-display text-2xl tracking-widest uppercase">
              No instructors found for this location yet.
            </div>
          )}

        </div>
      </section>

      <section className="py-24 bg-primary text-center">
        <div className="container mx-auto px-4">
          <h2 className="font-display text-5xl md:text-7xl uppercase tracking-widest mb-8 text-white">Ready to Work?</h2>
          <Button className="bg-black hover:bg-white hover:text-black text-white font-display tracking-widest text-2xl px-12 py-8 rounded-none transition-colors border border-black">
            GET STARTED TODAY
          </Button>
        </div>
      </section>

      <Newsletter />
    </Layout>
  );
}

